package com.example

/**
 * Grade 11 Mathematics Syllabus Question Bank for Live Exam Hall.
 * Covers Terms 1, 2, and 3 with 60 distinct syllabus topic slots per term.
 * Permutes slots with coprime 7 so each paper presents all 60 syllabus points in unique sequence,
 * and varies mathematical coefficients across papers 1 to 30.
 */
object MathGrade11QuestionBank {

  fun getQuestion(term: Int, paperIdx: Int, qNum: Int): MockExamQuestion {
    val cleanPaper = if (paperIdx in 1..30) paperIdx else 1
    val cleanQ = if (qNum in 1..60) qNum else 1
    val effectiveSlot = ((cleanQ - 1 + (cleanPaper - 1) * 7) % 60) + 1
    return when (term) {
      1 -> getTerm1Question(cleanPaper, cleanQ, effectiveSlot)
      2 -> getTerm2Question(cleanPaper, cleanQ, effectiveSlot)
      else -> getTerm3Question(cleanPaper, cleanQ, effectiveSlot)
    }
  }

  // ==========================================================================
  // GRADE 11 - TERM 1 (Slots 1 to 60)
  // ==========================================================================
  private fun getTerm1Question(paperIdx: Int, qNum: Int, slot: Int): MockExamQuestion {
    val v = paperIdx - 1
    val (topic, quad) = when (slot) {
      in 1..8 -> "වර්ගජ සමීකරණ (Quadratic Equations)" to run {
        val p = 2 + (v % 5)
        val q = 3 + ((v + 1) % 4)
        val sum = p + q
        val prod = p * q
        val quadList = listOf(
          Quad("x² - ${sum}x + $prod = 0 වර්ගජ සමීකරණයේ මූල (Roots) මොනවාද?", listOf("x = $p හෝ x = $q", "x = -$p හෝ x = -$q", "x = 1 හෝ x = $prod", "x = 0"), 1, "(x - $p)(x - $q) = 0 බැවින් x = $p හෝ x = $q වේ."),
          Quad("x² + ${p + 1}x = 0 සමීකරණයේ මූල මොනවාද?", listOf("x = 0 හෝ x = -${p + 1}", "x = 0 හෝ x = ${p + 1}", "x = 1", "x = -1"), 1, "x(x + ${p + 1}) = 0 => x = 0 හෝ x = -${p + 1}."),
          Quad("ax² + bx + c = 0 වර්ගජ සමීකරණයේ මූල සෙවීමේ සම්මත වර්ගජ සූත්‍රය කුමක්ද?", listOf("x = [-b ± √(b² - 4ac)] / 2a", "x = [-b ± √(b² + 4ac)] / 2a", "x = [b ± √(b² - 4ac)] / 2a", "x = -b / 2a"), 1, "වර්ගජ සූත්‍රය: x = (-b ± √(b² - 4ac)) / (2a) වේ."),
          Quad("x² - 9 = 0 වර්ගජ සමීකරණයේ මූල මොනවාද?", listOf("x = 3 හෝ x = -3", "x = 3 පමණි", "x = 9 හෝ x = -9", "x = 0"), 1, "x² = 9 => x = ±3 වේ."),
          Quad("වර්ගජ සමීකරණයක විවේචකය Δ = b² - 4ac > 0 වන විට මූලයන්ගේ ස්වභාවය කුමක්ද?", listOf("තාත්වික සහ එකිනෙකට වෙනස් මූල 2ක් ඇත", "සමාන මූල 2ක් ඇත", "තාත්වික මූල නැත", "ශුන්‍ය වේ"), 1, "Δ > 0 විට එකිනෙකට වෙනස් තාත්වික මූල 2ක් පවතී."),
          Quad("විවේචකය b² - 4ac = 0 වන විට ලැබෙන මූලයන්ගේ ස්වභාවය කුමක්ද?", listOf("තාත්වික සහ එකිනෙකට සමාන මූල 2ක් (සමපාත මූල)", "වෙනස් මූල", "මූල නැත", "අනන්තය"), 1, "Δ = 0 විට මූලයන් තාත්වික හා සමපාත වේ."),
          Quad("(x - 5)² = 0 සමීකරණයේ විසඳුම කුමක්ද?", listOf("x = 5 (සමපාත මූල)", "x = ±5", "x = -5", "x = 25"), 1, "x - 5 = 0 => x = 5 වේ."),
          Quad("2x² - 8 = 0 සමීකරණයේ මූල මොනවාද?", listOf("x = 2 හෝ x = -2", "x = 4 හෝ x = -4", "x = 2 පමණි", "x = 8"), 1, "2x² = 8 => x² = 4 => x = ±2 වේ.")
        )
        quadList[(slot - 1 + v).mod(quadList.size)]
      }
      in 9..16 -> "වර්ගජ ශ්‍රිත ප්‍රස්ථාර" to run {
        val h = 1 + (v % 4)
        val k = 2 + (v % 5)
        val graphList = listOf(
          Quad("y = (x - $h)² + $k වර්ගජ ශ්‍රිතයේ හැරවුම් ලක්ෂ්‍යයේ (ශීර්ෂයේ) ඛණ්ඩාංක මොනවාද?", listOf("($h, $k)", "(-$h, $k)", "($h, -$k)", "(0, $k)"), 1, "y = (x - h)² + k හි අවම ලක්ෂ්‍යය (h, k) = ($h, $k) වේ."),
          Quad("y = (x - $h)² + $k ප්‍රස්ථාරයේ සමමිතික අක්ෂයේ සමීකරණය කුමක්ද?", listOf("x = $h", "y = $k", "x = -$h", "y = $h"), 1, "සමමිතික අක්ෂය යනු ශීර්ෂය හරහා යන x = h රේඛාවයි: x = $h."),
          Quad("y = (x - 3)² - 4 ප්‍රස්ථාරයේ ශ්‍රිතයේ අවම අගය (Minimum value) කුමක්ද?", listOf("-4", "3", "-3", "4"), 1, "ශීර්ෂයේ y-ඛණ්ඩාංකය අවම අගය වේ: -4."),
          Quad("y = -(x - 2)² + 5 ප්‍රස්ථාරයේ උපරිම අගය කුමක්ද?", listOf("5", "2", "-2", "-5"), 1, "x² හි සංගුණකය සෘණ බැවින් උපරිම ලක්ෂ්‍යයක් ඇත: උපරිම අගය 5 වේ."),
          Quad("y = x² - 4 ප්‍රස්ථාරය x-අක්ෂය ඡේදනය කරන ලක්ෂ්‍ය මොනවාද?", listOf("(2, 0) සහ (-2, 0)", "(4, 0) සහ (-4, 0)", "(0, -4)", "(0, 2)"), 1, "y = 0 විට x² - 4 = 0 => x = ±2. එබැවින් (2, 0) සහ (-2, 0)."),
          Quad("y = ax² + bx + c හි a > 0 වන විට ප්‍රස්ථාරයේ හැඩය කෙසේද?", listOf("යටි පැත්තට උත්තල (U හැඩය - අවම ලක්ෂ්‍යයක් සහිත)", "උඩු පැත්තට උත්තල (∩ හැඩය)", "සරල රේඛාවකි", "වෘත්තයකි"), 1, "a > 0 විට ප්‍රස්ථාරය අවම ලක්ෂ්‍යයක් සහිත U හැඩයක් ගනී."),
          Quad("y = (x + 4)² හි ශීර්ෂයේ ඛණ්ඩාංක මොනවාද?", listOf("(-4, 0)", "(4, 0)", "(0, 4)", "(0, -4)"), 1, "y = (x - (-4))² + 0 බැවින් ශීර්ෂය (-4, 0) වේ."),
          Quad("ප්‍රස්ථාරයක y > 0 වන x හි අගය පරාසය යනු කුමක්ද?", listOf("ප්‍රස්ථාරය x-අක්ෂයට ඉහළින් පිහිටන x අගයන්", "x-අක්ෂයට පහළින් පිහිටන අගයන්", "x-අක්ෂය මත ලක්ෂ්‍ය", "අවම ලක්ෂ්‍යය"), 1, "y > 0 යනු ප්‍රස්ථාරය x-අක්ෂයෙන් උඩින් පිහිටන කලාපයයි.")
        )
        graphList[(slot - 9 + v).mod(graphList.size)]
      }
      in 17..24 -> "දර්ශක හා ලඝුගණක II" to run {
        val log2List = listOf(
          Quad("345.6 සංඛ්‍යාවේ ලඝුගණකයේ පූර්ණාංශය (Characteristic) කොපමණද?", listOf("2", "3", "1", "0"), 1, "345.6 = 3.456 × 10² බැවින් පූර්ණාංශය 2 වේ."),
          Quad("0.0456 සංඛ්‍යාවේ ලඝුගණකයේ පූර්ණාංශය කුමක්ද?", listOf("2̄ (සෘණ 2)", "2", "-1", "3̄"), 1, "0.0456 = 4.56 × 10⁻² බැවින් පූර්ණාංශය 2̄ වේ."),
          Quad("log 2 = 0.3010 නම්, log 20 හි අගය කුමක්ද?", listOf("1.3010", "2.3010", "0.6020", "3.010"), 1, "log 20 = log(2 × 10) = log 2 + log 10 = 0.3010 + 1 = 1.3010."),
          Quad("log 2 = 0.3010 නම්, log 4 හි අගය කුමක්ද?", listOf("0.6020", "0.3010", "1.3010", "0.9030"), 1, "log 4 = log(2²) = 2 log 2 = 2 × 0.3010 = 0.6020 වේ."),
          Quad("log 3 = 0.4771 සහ log 2 = 0.3010 නම්, log 6 හි අගය කුමක්ද?", listOf("0.7781", "0.1761", "1.4771", "0.1436"), 1, "log 6 = log(2 × 3) = log 2 + log 3 = 0.3010 + 0.4771 = 0.7781."),
          Quad("log x = 2.4500 නම්, x සංඛ්‍යාවේ පූර්ණ සංඛ්‍යා කොටසේ ඉලක්කම් කීයක් තිබේද?", listOf("ඉලක්කම් 3ක්", "ඉලක්කම් 2ක්", "ඉලක්කම් 4ක්", "ඉලක්කම් 1ක්"), 1, "පූර්ණාංශය n නම් ඉලක්කම් n + 1 කි: 2 + 1 = 3."),
          Quad("antilog(1.0000) හි අගය කුමක්ද?", listOf("10", "1", "100", "0"), 1, "10¹ = 10 බැවින් ප්‍රතිලඝුගණකය 10 වේ."),
          Quad("log(a / b) ලඝුගණක නීතිය අනුව කුමක්ද?", listOf("log a - log b", "log a / log b", "log a + log b", "log(a - b)"), 1, "බෙදීමේදී ලඝුගණක අඩු වේ: log(a/b) = log a - log b.")
        )
        log2List[(slot - 17 + v).mod(log2List.size)]
      }
      in 25..32 -> "අනුපාත හා සමානුපාත" to run {
        val a = 2 + (v % 3)
        val b = 3 + (v % 3)
        val ratioList = listOf(
          Quad("රු. 10 000 ක මුදලක් $a : $b අනුපාතයට දෙදෙනෙකු අතර බෙදූ විට පළමු පුද්ගලයාට ලැබෙන මුදල කොපමණද?", listOf("රු. ${(10000 * a) / (a + b)}", "රු. 4 000", "රු. 5 000", "රු. 6 000"), 1, "මුළු කොටස් = ${a + b}. පළමු කොටස = (10 000 / ${a + b}) × $a = රු. ${(10000 * a) / (a + b)} වේ."),
          Quad("මිනිසුන් 6 දෙනෙකුට දින 10 කින් නිම කළ හැකි කාර්යයක් මිනිසුන් 4 දෙනෙකුට නිම කිරීමට දින කීයක් ගතවේද?", listOf("දින 15", "දින 12", "දින 8", "දින 20"), 1, "ප්‍රතිලෝම සමානුපාතික: මිනිස් දින = 6 × 10 = 60. දින ගණන = 60 / 4 = දින 15 වේ."),
          Quad("a : b = 2 : 3 සහ b : c = 4 : 5 නම්, a : b : c අනුපාතය කුමක්ද?", listOf("8 : 12 : 15", "2 : 4 : 5", "6 : 8 : 10", "8 : 10 : 15"), 1, "b පොදු කළ විට: a : b = 8 : 12, b : c = 12 : 15 => a : b : c = 8 : 12 : 15."),
          Quad("සිතියමක පරිමාණය 1 : 50 000 කි. සිතියමේ 4 cm ක දුරකින් දැක්වෙන පොළොවේ සැබෑ දුර කිලෝමීටර කීයක්ද?", listOf("2 km", "4 km", "20 km", "0.2 km"), 1, "සැබෑ දුර = 4 × 50 000 cm = 200 000 cm = 2 000 m = 2 km වේ."),
