          Quad("4x² - 25 හි සාධක මොනවාද?", listOf("(2x - 5)(2x + 5)", "(4x - 5)(4x + 5)", "(2x - 5)²", "2x(2x - 25)"), 1, "(2x)² - 5² = (2x - 5)(2x + 5) වේ."),
          Quad("(x + 3)² - 16 හි සාධක මොනවාද?", listOf("(x + 7)(x - 1)", "(x + 3 - 4)²", "(x - 1)²", "(x + 7)²"), 1, "[(x + 3) - 4][(x + 3) + 4] = (x - 1)(x + 7) වේ."),
          Quad("x² + 7x + 12 හි සාධක මොනවාද?", listOf("(x + 3)(x + 4)", "(x + 2)(x + 6)", "(x - 3)(x - 4)", "(x + 1)(x + 12)"), 1, "ගුණිතය 12 සහ එකතුව 7 වන සංඛ්‍යා 3 සහ 4 වේ: (x + 3)(x + 4)."),
          Quad("2x² + 5x + 3 හි සාධක මොනවාද?", listOf("(2x + 3)(x + 1)", "(2x + 1)(x + 3)", "(2x - 3)(x - 1)", "2x(x + 3)"), 1, "2x² + 2x + 3x + 3 = 2x(x + 1) + 3(x + 1) = (2x + 3)(x + 1)."),
          Quad("(a + b)² - (a - b)² ප්‍රසාරණය කර සුළු කළ විට ලැබෙන්නේ කුමක්ද?", listOf("4ab", "2a² + 2b²", "0", "2ab"), 1, "(a² + 2ab + b²) - (a² - 2ab + b²) = 4ab වේ.")
        )
        fList[(slot - 49 + v).mod(fList.size)]
      }
      else -> "1 වන වාර ආදර්ශ විභාග බහුවරණ ගැටලු" to run {
        val t1ExamList = listOf(
          Quad("x² - 5x = 0 සමීකරණයේ ධන මූලය කුමක්ද?", listOf("5", "0", "-5", "25"), 1, "x(x - 5) = 0 => x = 0 හෝ x = 5. ධන මූලය 5 වේ."),
          Quad("y = (x - 1)² + 4 හි සමමිතික අක්ෂය කුමක්ද?", listOf("x = 1", "y = 4", "x = -1", "y = 1"), 1, "සමමිතික අක්ෂය x = 1 වේ."),
          Quad("log 1000 = x නම් x හි අගය කුමක්ද?", listOf("3", "2", "10", "1"), 1, "10³ = 1000 => x = 3."),
          Quad("රු. 20 000 ක ණයකට වසරක පොලිය රු. 2 400 ක් නම් වාර්ෂික පොලී අනුපාතිකය කුමක්ද?", listOf("12%", "10%", "15%", "8%"), 1, "R = (2400 / 20000) × 100% = 12%."),
          Quad("කාර්තුවකට රු. 2 500 ක් වරිපනම් බදු ගෙවන ගොඩනැගිල්ලක වාර්ෂික බද්ද කොපමණද?", listOf("රු. 10 000", "රු. 5 000", "රු. 7 500", "රු. 20 000"), 1, "2 500 × 4 = රු. 10 000 වේ."),
          Quad("කෝණ තුනක එකතුව 180° වන රූපය කුමක්ද?", listOf("තල ත්‍රිකෝණය", "චතුරස්‍රය", "පංචස්‍රය", "වෘත්තය"), 1, "ත්‍රිකෝණයක අභ්‍යන්තර කෝණ ඓක්‍යය 180° කි.")
        )
        t1ExamList[(slot - 55 + v).mod(t1ExamList.size)]
      }
    }

    return MockExamQuestion(
      id = qNum,
      questionText = "ආදර්ශ පත්‍රය ${String.format("%02d", paperIdx)} • ප්‍රශ්නය $qNum: ${quad.q}",
      options = quad.opts,
      correctOption = quad.c,
      explanation = quad.exp,
      topicName = topic
    )
  }

  // ==========================================================================
  // GRADE 11 - TERM 2 (Slots 1 to 60)
  // ==========================================================================
  private fun getTerm2Question(paperIdx: Int, qNum: Int, slot: Int): MockExamQuestion {
    val v = paperIdx - 1
    val (topic, quad) = when (slot) {
      in 1..8 -> "සමාන්තර ශ්‍රේඪි (Arithmetic Progressions)" to run {
        val a = 2 + (v % 5)
        val d = 3 + (v % 4)
        val apList = listOf(
          Quad("ප්‍රථම පදය $a සහ පොදු අන්තරය $d වූ සමාන්තර ශ්‍රේඪියේ 10 වන පදය (T₁₀) කුමක්ද?", listOf("${a + 9 * d}", "${a + 10 * d}", "${a * 10}", "${a + 8 * d}"), 1, "T_n = a + (n - 1)d => T₁₀ = $a + (10 - 1)($d) = $a + ${9 * d} = ${a + 9 * d} වේ."),
          Quad("3, 7, 11, 15, ... සමාන්තර ශ්‍රේඪියේ පොදු අන්තරය (d) කුමක්ද?", listOf("4", "3", "7", "5"), 1, "d = T₂ - T₁ = 7 - 3 = 4 වේ."),
          Quad("ප්‍රථම පදය a සහ අවසාන පදය l වූ සමාන්තර ශ්‍රේඪියක මුල් පද n හි එකතුව (S_n) සෙවීමේ සූත්‍රය කුමක්ද?", listOf("S_n = n/2 (a + l)", "S_n = n (a + l)", "S_n = n/2 (a - l)", "S_n = 2n (a + l)"), 1, "S_n = n/2 (a + l) හෝ S_n = n/2 [2a + (n - 1)d] වේ."),
          Quad("2, 4, 6, 8, ... පළමු ඉරට්ටේ සංඛ්‍යා 20 හි එකතුව (S₂₀) කොපමණද?", listOf("420", "400", "210", "440"), 1, "S₂₀ = 20/2 [2(2) + 19(2)] = 10 [4 + 38] = 10 × 42 = 420."),
          Quad("සමාන්තර ශ්‍රේඪියක T₁ = 5 සහ T₅ = 17 නම් එහි පොදු අන්තරය (d) කුමක්ද?", listOf("3", "4", "2", "5"), 1, "T₅ = a + 4d => 17 = 5 + 4d => 4d = 12 => d = 3."),
          Quad("1, 2, 3, ..., 100 දක්වා වූ පළමු ස්වාභාවික සංඛ්‍යා 100 හි එකතුව කුමක්ද?", listOf("5050", "5000", "5100", "10000"), 1, "S_n = n(n + 1) / 2 = 100 × 101 / 2 = 5050 වේ."),
          Quad("සමාන්තර ශ්‍රේඪියක 5 වන පදය 15 ද 6 වන පදය 18 ද වේ නම් පොදු අන්තරය කුමක්ද?", listOf("3", "4", "15", "18"), 1, "d = T₆ - T₅ = 18 - 15 = 3 වේ."),
          Quad("7, 10, 13, ... ශ්‍රේඪියේ කීවන පදය 37 වේද?", listOf("11 වන පදය", "10 වන පදය", "12 වන පදය", "9 වන පදය"), 1, "37 = 7 + (n - 1)3 => 30 = 3(n - 1) => n - 1 = 10 => n = 11.")
        )
        apList[(slot - 1 + v).mod(apList.size)]
      }
      in 9..16 -> "ගුණෝත්තර ශ්‍රේඪි (Geometric Progressions)" to run {
        val gpList = listOf(
          Quad("2, 6, 18, 54, ... ගුණෝත්තර ශ්‍රේඪියේ පොදු අනුපාතය (r) කුමක්ද?", listOf("3", "2", "4", "6"), 1, "r = T₂ / T₁ = 6 / 2 = 3 වේ."),
          Quad("ප්‍රථම පදය a සහ පොදු අනුපාතය r වූ ගුණෝත්තර ශ්‍රේඪියක n වන පදය (T_n) සෙවීමේ සූත්‍රය කුමක්ද?", listOf("T_n = a r^(n-1)", "T_n = a r^n", "T_n = a + r^(n-1)", "T_n = (ar)^n"), 1, "ගුණෝත්තර ශ්‍රේඪියක n වන පදය T_n = a r^(n-1) වේ."),
          Quad("3, 6, 12, 24, ... ගුණෝත්තර ශ්‍රේඪියේ 5 වන පදය (T₅) කුමක්ද?", listOf("48", "36", "96", "24"), 1, "T₅ = 3 × 2⁴ = 3 × 16 = 48 වේ."),
          Quad("ගුණෝත්තර ශ්‍රේඪියක T₁ = 5 සහ T₂ = 10 නම් එහි 4 වන පදය කුමක්ද?", listOf("40", "20", "30", "50"), 1, "r = 10 / 5 = 2. T₄ = 5 × 2³ = 5 × 8 = 40 වේ."),
          Quad("1, 3, 9, 27, ... ශ්‍රේඪියේ පොදු අනුපාතය කුමක්ද?", listOf("3", "1/3", "2", "9"), 1, "r = 3 / 1 = 3 වේ."),
          Quad("ප්‍රථම පදය 4 සහ r = 1/2 වූ ගුණෝත්තර ශ්‍රේඪියේ 3 වන පදය කුමක්ද?", listOf("1", "2", "1/2", "4"), 1, "T₃ = 4 × (1/2)² = 4 × 1/4 = 1 වේ."),
          Quad("2, -4, 8, -16, ... ගුණෝත්තර ශ්‍රේඪියේ පොදු අනුපාතය (r) කුමක්ද?", listOf("-2", "2", "-4", "1/2"), 1, "r = -4 / 2 = -2 වේ."),
          Quad("ගුණෝත්තර ශ්‍රේඪියක පළමු පද 3 వరుසින් a, ar, ar² නම් ඒවායේ ගුණිතය කුමක්ද?", listOf("a³ r³", "a³ r²", "3ar", "a r³"), 1, "a × ar × ar² = a³ r³ = (ar)³ වේ.")
        )
        gpList[(slot - 9 + v).mod(gpList.size)]
      }
      in 17..24 -> "න්‍යාස (Matrices)" to run {
        val matList = listOf(
          Quad("පේළි 2ක් සහ තීරු 3ක් ඇති න්‍යාසයක ගණය (Order of matrix) කුමක්ද?", listOf("2 × 3", "3 × 2", "6", "2 + 3"), 1, "ගණය = පේළි ගණන × තීරු ගණන = 2 × 3 වේ."),
          Quad("A = [2  3] සහ B = [4  1] නම්, A + B න්‍යාසය කුමක්ද?", listOf("[6  4]", "[8  3]", "[2  2]", "[6  2]"), 1, "අනුරූප මූලද්‍රව්‍ය එකතු කිරීමෙන්: [2+4  3+1] = [6  4] වේ."),
          Quad("A = [1  2] නම්, 3A (අදිශ ගුණිතය) කුමක්ද?", listOf("[3  6]", "[1  6]", "[4  5]", "[3  2]"), 1, "සෑම මූලද්‍රව්‍යයක්ම 3න් ගුණ කළ විට [3  6] ලැබේ."),
          Quad("පේළි ගණන සහ තීරු ගණන සමාන වූ න්‍යාසයක් හඳුන්වන්නේ කෙසේද?", listOf("සමචතුරස්‍ර න්‍යාසයක් (Square matrix)", "පේළි න්‍යාසයක්", "තීරු න්‍යාසයක්", "ශූන්‍ය න්‍යාසයක්"), 1, "පේළි = තීරු (උදා: 2×2, 3×3) සමචතුරස්‍ර න්‍යාස වේ."),
