          Quad("ප්‍රතිස්ථාපනය සහිතව (With replacement) බෝල ගැනීමේදී එක් එක් වාරයේ සම්භාවිතාවන්ට කුමක් සිදුවේද?", listOf("සම්භාවිතාවන් නොවෙනස්ව පවතී (ස්වාධීන වේ)", "සම්භාවිතාව අඩුවේ", "වැඩිවේ", "ශුන්‍ය වේ"), 1, "ආපසු බඳුනට දමන බැවින් ඊළඟ වාරයේ සම්භාවිතාව වෙනස් නොවේ."),
          Quad("A සහ B පරස්පර පරිවර්ජිත සිදුවීම් (Mutually exclusive events) නම් P(A ∩ B) කුමක්ද?", listOf("0 (එකවර සිදුවිය නොහැක)", "1", "P(A) × P(B)", "0.5"), 1, "පරස්පර පරිවර්ජිත සිදුවීම් එකවර සිදුවිය නොහැක: P(A ∩ B) = 0."),
          Quad("සාධාරණ දාදු කැටයක් දෙවරක් දැමූ විට ලැබිය හැකි මුළු නියැදි අවකාශයේ මූලද්‍රව්‍ය ගණන කුමක්ද?", listOf("36 (6 × 6)", "12", "6", "64"), 1, "6 × 6 = 36 ක් ප්‍රතිඵල ලැබේ.")
        )
        treeList[(slot - 33 + v).mod(treeList.size)]
      }
      in 41..48 -> "අසමානතා (Inequalities)" to run {
        val ineqList = listOf(
          Quad("2x - 3 ≤ 5 අසමානතාව විසඳූ විට x හි විසඳුම කුමක්ද?", listOf("x ≤ 4", "x ≤ 1", "x ≥ 4", "x < 4"), 1, "2x ≤ 8 => x ≤ 4 වේ."),
          Quad("-2x < 6 අසමානතාවය සෘණ සංඛ්‍යාවකින් බෙදූ විට අසමානතා ලකුණට සිදුවන්නේ කුමක්ද?", listOf("අසමානතා ලකුණ ප්‍රතිවිරුද්ධ දිශාවට හැරී x > -3 වේ", "ලකුණ වෙනස් නොවේ", "සමාන ලකුණක් වේ", "ශුන්‍ය වේ"), 1, "සෘණ අගයකින් ගුණ කිරීමේදී හෝ බෙදීමේදී අසමානතා ලකුණ මාරු වේ: x > -3."),
          Quad("3x + 1 > 10 අසමානතාවය තෘප්ත කරන කුඩාම නිඛිලය කුමක්ද?", listOf("4", "3", "5", "10"), 1, "3x > 9 => x > 3. කුඩාම නිඛිලය 4 වේ."),
          Quad("x ≤ 3 සංඛ්‍යා රේඛාවක නිරූපණය කිරීමේදී 3 ලක්ෂ්‍යය මත ලකුණු කරන්නේ කෙසේද?", listOf("පිරවූ (කළු කළ) තිත් කවයක් සහ වමට ඊතලය", "හිස් කවයක් සහ දකුණට ඊතලය", "හිස් කවයක් පමණි", "තිතක් නැත"), 1, "≤ ලකුණ ඇති විට අගය ඇතුළත් බැවින් පිරවූ තිතක් යොදයි."),
          Quad("-1 < x ≤ 4 අසමානතාවය තෘප්ත කරන පූර්ණ සංඛ්‍යා ගණන කොපමණද?", listOf("5 (0, 1, 2, 3, 4)", "4", "6", "3"), 1, "පූර්ණ සංඛ්‍යා: 0, 1, 2, 3, 4 (සංඛ්‍යා 5කි)."),
          Quad("5 - x ≥ 2 අසමානතාවයේ විසඳුම කුමක්ද?", listOf("x ≤ 3", "x ≥ 3", "x ≤ -3", "x ≥ -3"), 1, "-x ≥ -3 => x ≤ 3 වේ."),
          Quad("x/2 > 3 අසමානතාවයේ විසඳුම කුමක්ද?", listOf("x > 6", "x < 6", "x > 1.5", "x = 6"), 1, "x > 3 × 2 => x > 6 වේ."),
          Quad("2x + 4 < 0 නම් x හි අගය කුමක්ද?", listOf("x < -2", "x > -2", "x < 2", "x = -2"), 1, "2x < -4 => x < -2.")
        )
        ineqList[(slot - 41 + v).mod(ineqList.size)]
      }
      in 49..54 -> "ප්‍රස්ථාරික ක්‍රම මඟින් සමීකරණ විසඳීම" to run {
        val rootList = listOf(
          Quad("y = x² - 2x - 3 ප්‍රස්ථාරය x-අක්ෂය ඡේදනය කරන ලක්ෂ්‍යවල x ඛණ්ඩාංක මඟින් ලැබෙන්නේ කුමක්ද?", listOf("x² - 2x - 3 = 0 සමීකරණයේ මූල (විසඳුම්)", "අවම අගය", "y-අන්තඃඛණ්ඩය", "අනුක්‍රමණය"), 1, "x-අක්ෂය මත y = 0 බැවින් ඡේදනය වන x අගයන් සමීකරණයේ මූල වේ."),
          Quad("y = x² ප්‍රස්ථාරය සහ y = 4 සරල රේඛාව ඡේදනය වන ලක්ෂ්‍යවල x අගයන් මොනවාද?", listOf("x = 2 සහ x = -2", "x = 4 සහ x = -4", "x = 16", "x = 0"), 1, "x² = 4 => x = ±2 වේ."),
          Quad("y = (x - 2)² + 1 ප්‍රස්ථාරය x-අක්ෂය ඡේදනය නොකරන්නේ මන්ද?", listOf("එහි අවම අගය 1 ක් වන බැවින් (x-අක්ෂයට ඉහළින් පිහිටයි)", "අවම අගය සෘණ බැවින්", "සරල රේඛාවක් බැවින්", "මූල 2ක් ඇති බැවින්"), 1, "අවම අගය y = 1 වන අතර එය සම්පූර්ණයෙන්ම x-අක්ෂයට ඉහළින් පවතී."),
          Quad("ප්‍රස්ථාර දෙකක් ඡේදනය වන ලක්ෂ්‍යයේ ඛණ්ඩාංක මඟින් නිරූපණය කරන්නේ කුමක්ද?", listOf("එම සමීකරණ දෙකෙහි සමගාමී විසඳුම", "අසමානතාවක්", "පරිමිතියක්", "අනුක්‍රමණය"), 1, "ඡේදනය වන ලක්ෂ්‍යයේ ඛණ්ඩාංක සමීකරණ දෙකම එකවර තෘප්ත කරයි."),
          Quad("y = 2x + 1 සහ y = -x + 4 රේඛා දෙක ඡේදනය වන ලක්ෂ්‍යයේ x අගය කුමක්ද?", listOf("x = 1", "x = 2", "x = 3", "x = 0"), 1, "2x + 1 = -x + 4 => 3x = 3 => x = 1 වේ."),
          Quad("y = ax² + bx + c හි x-අක්ෂය ස්පර්ශ වන (තනි ලක්ෂ්‍යයකදී) අවස්ථාවේ විවේචකය කුමක්ද?", listOf("b² - 4ac = 0 (සමපාත මූල)", "b² - 4ac > 0", "b² - 4ac < 0", "1"), 1, "තනි ලක්ෂ්‍යයකදී ස්පර්ශ වන්නේ විවේචකය 0 වන විටය.")
        )
        rootList[(slot - 49 + v).mod(rootList.size)]
      }
      else -> "අවසාන O/L මහා පෙරහුරු විභාග ගැටලු" to run {
        val final11List = listOf(
          Quad("sin 30° + cos 60° හි අගය කුමක්ද?", listOf("1 (0.5 + 0.5)", "1/2", "√3", "0"), 1, "1/2 + 1/2 = 1 වේ."),
          Quad("අරය 7 cm වූ ගෝලයක මතුපිට වර්ගඵලය කොපමණද? (π = 22/7)", listOf("616 cm²", "154 cm²", "308 cm²", "1232 cm²"), 1, "A = 4πr² = 4 × (22/7) × 7² = 4 × 154 = 616 cm² වේ."),
          Quad("පළමු පදය 3 සහ පොදු අනුපාතය 2 වූ ගුණෝත්තර ශ්‍රේඪියේ 4 වන පදය කුමක්ද?", listOf("24", "18", "48", "12"), 1, "T₄ = 3 × 2³ = 3 × 8 = 24 වේ."),
          Quad("චක්‍රීය චතුරස්‍රයක එක් කෝණයක් 65° නම් ඊට සම්මුඛ කෝණය කුමක්ද?", listOf("115°", "65°", "125°", "90°"), 1, "180° - 65° = 115° වේ."),
          Quad("x² - 16 = 0 සමීකරණයේ ධන මූලය කුමක්ද?", listOf("4", "16", "8", "2"), 1, "x² = 16 => x = 4 වේ."),
          Quad("P(A) = 0.4 නම් P(A') (අනුපූරක සම්භාවිතාව) කුමක්ද?", listOf("0.6", "0.4", "1.4", "0"), 1, "P(A') = 1 - 0.4 = 0.6 වේ.")
        )
        final11List[(slot - 55 + v).mod(final11List.size)]
      }
    }

    return MockExamQuestion(
      id = qNum,
      questionText = "ආදර්ශ පත්‍රය ${String.format("%02d", paperIdx)} • ප්‍රශ්නය $qNum: ${quad.q}",
      options = quad.opts,
      correctOption = quad.c,
      explanation = quad.exp,
      topicName = topic
    )
  }

  private data class Quad(
    val q: String,
    val opts: List<String>,
    val c: Int,
    val exp: String
  )
}
